verses.tafsir:
[ <span class="arabic uthmani">وَقِيلَ يَا أَرْضُ ابْلَعِي مَاءَكِ</span> ] پاشان خوای گه‌وره‌ كه‌ كافران و بێباوه‌ڕانی له‌ناوبرد فه‌رمانی كرد به‌ زه‌ویه‌كه‌ ئه‌ی زه‌وی ئاوی خۆت قوت بده‌ [ <span class="arabic uthmani">وَيَا سَمَاءُ أَقْلِعِي</span> ] وه‌ ئه‌ی ئاسمان به‌سه‌ باران مه‌بارێنه‌ و با ببڕێته‌وه‌ [ <span class="arabic uthmani">وَغِيضَ الْمَاءُ</span> ] وه‌ ئاوه‌كه‌ ورده‌ ورده‌ كه‌می كرد تا سه‌ر زه‌وی وشك بوو [ <span class="arabic uthmani">وَقُضِيَ الْأَمْرُ</span> ] وه‌ فه‌رمانی خوای گه‌وره‌ جێبه‌جێ بوو كه‌ كافرانی هه‌موو له‌ناو بردو دواى بڕین
{كەشتییەكەی نوح پێغەمبەر - <span class="saw">صلی الله علیه وسلم</span> -  لە كوردستان لەنگەری گرت}
[ <span class="arabic uthmani">وَاسْتَوَتْ عَلَى الْجُودِيِّ</span> ] وه‌ كه‌شتیه‌كه‌ش له‌نگه‌ری گرت له‌سه‌ر شاخی (جودی) له‌ كوردستانی توركیا نزیك موسڵ [ <span class="arabic uthmani">وَقِيلَ بُعْدًا لِلْقَوْمِ الظَّالِمِينَ (٤٤)</span> ] وه‌ وترا: كه‌سانی زاڵم و كافرو بێباوه‌ڕ هه‌ر دووربن له‌ پاراستن و ڕه‌حمه‌تی خوای گه‌وره‌.

{شایەتی دانی سێیەم بە پاكێتی یوسف پێغەمبەر - <span class="saw">صلی الله علیه وسلم</span> -}
 [ <span class="arabic uthmani">قَالَ مَا خَطْبُكُنَّ إِذْ رَاوَدْتُنَّ يُوسُفَ عَنْ نَفْسِهِ</span> ] پاشا هه‌موو ئافره‌ته‌كانی كۆكرده‌وه‌و پێى وتن (مه‌به‌ستى خێزانه‌كه‌ى عه‌زیزى میصر بوو) ڕووداو و به‌سه‌رهاتی ئێوه‌ چی بوو كاتێك كه‌ داواتان له‌ یوسف كرد كه‌ خراپه‌تان له‌گه‌ڵدا بكات [ <span class="arabic uthmani">قُلْنَ حَاشَ لِلَّهِ مَا عَلِمْنَا عَلَيْهِ مِنْ سُوءٍ</span> ] وتیان: پاك و مونه‌ززه‌هی بۆ خوای گه‌وره‌ هیچ خراپه‌یه‌كمان له‌ یوسف - <span class="saw">صلی الله علیه وسلم</span> -  نه‌بینیوه‌ (ئه‌میش شایه‌تیدانى ئافره‌ته‌كانه‌ له‌سه‌ر پاكێتى یوسف - <span class="saw">صلی الله علیه وسلم</span> - )
{شایەتی دانی چوارەم بە پاكێتی یوسف پێغەمبەر - <span class="saw">صلی الله علیه وسلم</span> - }
 [ <span class="arabic uthmani">قَالَتِ امْرَأَتُ الْعَزِيزِ الْآنَ حَصْحَصَ الْحَقُّ أَنَا رَاوَدْتُهُ عَنْ نَفْسِهِ</span> ] خێزانه‌كه‌ی عه‌زیز وتی: ئێستا حه‌ق ده‌ركه‌وت و ئاشكرا بوو من بووم كه‌ داوام لێكرد كاری خراپه‌م له‌گه‌ڵدا بكات [ <span class="arabic uthmani">وَإِنَّهُ لَمِنَ الصَّادِقِينَ (٥١)</span> ] وه‌ یوسف له‌ ڕاستگۆیانه‌ له‌و قسانه‌ی كه‌ كردوویه‌تی (ئه‌میش شایه‌تیدانى خێزانی عه‌زیزه‌ له‌سه‌ر پاكێتى یوسف - <span class="saw">صلی الله علیه وسلم</span> - ).
